<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { getManagedServer, type ManagedServer } from '../api/server-mgmt'
import { collectHostMetric, configureHostMonitor, getHostHistory, getHostMonitor, type HostDiskIO, type HostMetric, type HostMonitor } from '../api/operations'
import MetricChart from '../components/MetricChart.vue'
const props=defineProps<{serverId?:number;embedded?:boolean}>()
const route=useRoute(),router=useRouter(),id=props.serverId??Number(route.params.id)
const server=ref<ManagedServer>(),monitor=ref<HostMonitor>(),samples=ref<HostMetric[]>([]),hours=ref(1),interval=ref(60),step=ref(60),loading=ref(false),pending=ref(false),error=ref(''),paused=ref(false)
const metricsDialog=ref(false),metricsAddress=ref(''),savingAddress=ref(false)
const selectedNet=ref(''),selectedDisk=ref(''),showAllDisks=ref(false);let timer:ReturnType<typeof setInterval>|undefined;let disposed=false
const metric=computed(()=>monitor.value?.metrics)
const times=computed(()=>samples.value.map(m=>m.collectedAt))
const gap=computed(()=>Math.max(interval.value*3,step.value*2))
const stale=computed(()=>metric.value&&Date.now()-new Date(metric.value.collectedAt).getTime()>Math.max(180,interval.value*3)*1000)
const series=(name:string,color:string,read:(m:HostMetric)=>number|null)=>({name,color,values:samples.value.map(read)})
const cpu=computed(()=>[series('CPU','#3979cc',m=>m.cpuUsagePercent),series('I/O 等待','#cf9537',m=>m.cpuWaitPercent),series('Steal','#c75c68',m=>m.cpuStealPercent??null)])
const memory=computed(()=>[series('内存使用率','#7666c6',m=>m.memUsagePercent)])
const load=computed(()=>[series('1 分钟','#3979cc',m=>m.load1),series('5 分钟','#3b9d83',m=>m.load5),series('15 分钟','#cf9537',m=>m.load15)])
const network=computed(()=>[series('入站','#3b9d83',m=>{const n=m.networks?.find(n=>n.name===selectedNet.value);return n?n.receivePerSecond/1048576:null}),series('出站','#3979cc',m=>{const n=m.networks?.find(n=>n.name===selectedNet.value);return n?n.transmitPerSecond/1048576:null})])
const io=computed(()=>[series('读取','#3b9d83',m=>{const d=m.diskIO?.find(d=>d.device===selectedDisk.value);return d?d.readPerSecond/1048576:null}),series('写入','#3979cc',m=>{const d=m.diskIO?.find(d=>d.device===selectedDisk.value);return d?d.writePerSecond/1048576:null})])
const iops=computed(()=>[series('读 IOPS','#3b9d83',m=>m.diskIO?.find(d=>d.device===selectedDisk.value)?.readIOPS??null),series('写 IOPS','#3979cc',m=>m.diskIO?.find(d=>d.device===selectedDisk.value)?.writeIOPS??null)])
const latency=computed(()=>[series('读平均时延','#3b9d83',m=>m.diskIO?.find(d=>d.device===selectedDisk.value)?.readAwaitMs??null),series('写平均时延','#3979cc',m=>m.diskIO?.find(d=>d.device===selectedDisk.value)?.writeAwaitMs??null)])
const diskBusy=computed(()=>[series('设备忙碌时间','#7666c6',m=>m.diskIO?.find(d=>d.device===selectedDisk.value)?.utilization??null)])
const runnable=computed(()=>[series('可运行任务','#3979cc',m=>m.runnableTasks??null),series('CPU 核数','#cf9537',m=>m.cpuCores)])
const pressure=computed(()=>[series('采样区间 CPU 等待','#c75c68',m=>m.cpuIntervalPressurePercent??null)])
const disks=computed(()=>metric.value?.diskIO||[])
const visibleDisks=computed(()=>disks.value.filter(d=>showAllDisks.value||!['partition','optical'].includes(d.kind||'')&&!/^sr\d+$/.test(d.device)))
const diskKind=(d:HostDiskIO)=>({disk:'整盘',partition:'分区',lvm:'LVM 逻辑卷',mapper:'映射设备',optical:'光驱',raid:'RAID',unknown:'未识别'}[d.kind||'unknown']||d.kind)
const diskName=(d:HostDiskIO)=>d.mappedName?`${d.mappedName}（${d.device}）`:d.device
const diskLabel=(d:HostDiskIO)=>`${diskName(d)} · ${diskKind(d)}${d.mountpoints?.length?' · '+d.mountpoints.join('、'):''}`
const diskRowClass=({row}:{row:HostDiskIO})=>row.device===selectedDisk.value?'selected-device':''
const currentDisk=computed(()=>disks.value.find(d=>d.device===selectedDisk.value))
function diskChain(d:HostDiskIO,seen=new Set<string>()):string {if(seen.has(d.device))return d.device;const next=new Set(seen).add(d.device);const parents=d.backingDevices?.length?d.backingDevices:d.parentDevice?[d.parentDevice]:[];const upstream=parents.map(name=>{const p=disks.value.find(p=>p.device===name);return p?diskChain(p,next):name}).join(' + ');return `${upstream?upstream+' → ':''}${diskName(d)}（${diskKind(d)}）`}
function ensureDisk(){if(!visibleDisks.value.some(d=>d.device===selectedDisk.value)){selectedDisk.value=(visibleDisks.value.find(d=>d.mountpoints?.includes('/'))||visibleDisks.value.find(d=>d.kind==='disk')||visibleDisks.value[0])?.device||''}}
watch([visibleDisks,showAllDisks],ensureDisk)
const ms=(v:number|null|undefined)=>v==null?'—':v.toFixed(2)+' ms'
const percent=(v:number|undefined)=>v==null?'未采集':v.toFixed(2)+'%'
const bytes=(n:number|undefined)=>n==null?'-':n>=1073741824?(n/1073741824).toFixed(2)+' GiB':n>=1048576?(n/1048576).toFixed(1)+' MiB':(n/1024).toFixed(1)+' KiB'
const time=(s:string|null|undefined)=>s?new Date(s).toLocaleString('zh-CN',{hour12:false}):'-'
async function refresh(){if(loading.value)return;loading.value=true;try{const [m,h]=await Promise.all([getHostMonitor(id),getHostHistory(id,hours.value)]);if(disposed)return;monitor.value=m;interval.value=m.config.intervalSeconds;samples.value=h.samples;step.value=h.stepSeconds;pending.value=m.collecting;error.value='';if(!selectedNet.value)selectedNet.value=(m.metrics?.networks.find(n=>/^(en|eth|bond|wl)/.test(n.name))||m.metrics?.networks[0])?.name||'';ensureDisk()}catch(e:any){error.value=e.message||'读取监控失败'}finally{loading.value=false}}
async function collect(){try{await collectHostMetric(id);pending.value=true;await refresh()}catch(e:any){ElMessage.error(e.message)}}
async function saveAddress(){savingAddress.value=true;try{await configureHostMonitor(id,!!monitor.value?.config.enabled,interval.value,metricsAddress.value.trim());metricsDialog.value=false;await refresh();await collect()}finally{savingAddress.value=false}}
async function save(enabled:boolean){await configureHostMonitor(id,enabled,interval.value);ElMessage.success(enabled?'已启用后台连续采集':'已关闭后台连续采集');await refresh();if(enabled)await collect()}
onMounted(async()=>{server.value=await getManagedServer(id);await refresh();timer=setInterval(()=>{if(!paused.value||pending.value)refresh()},3000)})
onUnmounted(()=>{disposed=true;if(timer)clearInterval(timer)})
</script>
<template><div class="host-monitor"><div class="heading"><div><el-button v-if="!embedded" text @click="router.push('/servers')">← 主机管理</el-button><h3>{{server?.remark||server?.host||'主机监控'}} <small>{{server?.host}}</small></h3></div><div class="actions"><el-select v-model="hours" style="width:130px" @change="refresh"><el-option label="最近 1 小时" :value="1"/><el-option label="最近 6 小时" :value="6"/><el-option label="最近 24 小时" :value="24"/><el-option label="最近 48 小时" :value="48"/></el-select><el-button @click="paused=!paused">{{paused?'恢复刷新':'暂停刷新'}}</el-button><el-button @click="metricsAddress=monitor?.config.metricsURL||metric?.sourceURL||'';metricsDialog=true">指标地址</el-button><el-button :loading="pending" @click="collect">立即采集</el-button><el-button type="primary" @click="router.push({path:'/inspections',query:{host:id}})">发起巡检</el-button></div></div>
<el-alert v-if="error||monitor?.config.lastError" type="error" :title="error||monitor?.config.lastError" :closable="false" show-icon/>
<div class="collection"><div><el-tag :type="monitor?.config.enabled?'success':'info'">{{monitor?.config.enabled?'后台连续采集':'单次采样'}}</el-tag><span>最近样本：{{time(metric?.collectedAt)}}</span><el-tag v-if="stale" type="warning">样本已过期</el-tag><span v-if="pending">正在连接并采集，页面可稍后查看</span></div><div><span>采集间隔</span><el-select v-model="interval" style="width:100px" @change="save(!!monitor?.config.enabled)"><el-option :value="30" label="30 秒"/><el-option :value="60" label="60 秒"/><el-option :value="300" label="5 分钟"/></el-select><el-switch :model-value="!!monitor?.config.enabled" @change="(v: string | number | boolean)=>save(!!v)"/></div></div>
<div class="source-info">监控来源：HTTP · node_exporter {{metric?.exporterVersion||''}} · {{metric?.sourceURL||monitor?.config.metricsURL||`http://${server?.host||''}:9100/metrics`}}</div>
<template v-if="metric"><div class="cards"><div><span>CPU 使用率</span><strong>{{metric.cpuUsagePercent.toFixed(1)}}<small>%</small></strong><p>{{metric.cpuCores}} 核 · I/O 等待 {{metric.cpuWaitPercent.toFixed(1)}}%</p></div><div><span>内存使用率</span><strong>{{metric.memUsagePercent.toFixed(1)}}<small>%</small></strong><p>可用 {{bytes(metric.memAvailableBytes)}} / {{bytes(metric.memTotalBytes)}}</p></div><div><span>系统负载</span><strong>{{metric.load1.toFixed(2)}}</strong><p>5 分钟 {{metric.load5.toFixed(2)}} · 15 分钟 {{metric.load15.toFixed(2)}}</p></div><div><span>Swap 使用</span><strong>{{bytes(metric.swapUsedBytes)}}</strong><p>总量 {{bytes(metric.swapTotalBytes)}}</p></div></div>
<div class="charts"><MetricChart title="CPU 使用与等待" :times="times" :series="cpu" unit="%" :max="100" :gap-seconds="gap"/><MetricChart title="内存" :times="times" :series="memory" unit="%" :max="100" :gap-seconds="gap"/><MetricChart title="系统负载" :times="times" :series="load" :gap-seconds="gap"/><div class="chart-wrap"><el-select v-model="selectedNet" size="small"><el-option v-for="n in metric.networks" :key="n.name" :value="n.name" :label="n.name"/></el-select><MetricChart title="网络速率" :times="times" :series="network" unit="MiB/s" :gap-seconds="gap"/></div></div>
<div class="data-card"><h4>CPU 竞争与调度</h4><div class="cpu-summary"><div>Steal / 虚拟 CPU 被占用时间<strong>{{percent(metric.cpuStealPercent)}}</strong></div><div>可运行任务 / CPU 核数<strong>{{metric.runnableTasks??'未采集'}} / {{metric.cpuCores}}</strong></div><div>等待 I/O 的任务<strong>{{metric.blockedTasks??'未采集'}}</strong></div><div>平均调度等待<strong>{{ms(metric.cpuSchedulingWaitMs)}}</strong></div><div>CPU PSI（采样区间）<strong>{{metric.cpuIntervalPressurePercent!=null?percent(metric.cpuIntervalPressurePercent):'不可用'}}</strong></div></div><p class="note">Steal 表示内核记录的虚拟 CPU 非自愿等待时间；0% 不能排除所有宿主机调度争用。可运行任务包含正在运行、等待 CPU 的线程和采集进程。负载也包含不可中断睡眠任务，不能直接当作 CPU 竞争率。虚拟化平台的 CPU Ready 需由宿主机提供。</p><div class="charts"><MetricChart title="可运行任务与 CPU 核数" :times="times" :series="runnable" unit="个" :gap-seconds="gap"/><MetricChart v-if="metric.cpuIntervalPressurePercent!=null" title="CPU 等待压力 PSI · some" :times="times" :series="pressure" unit="%" :max="100" :gap-seconds="gap"/><div v-else class="capability"><el-alert :title="metric.cpuPressureError||'该样本未采集 CPU PSI，等待 HTTP 采样'" type="info" :closable="false"/><p class="note">调度等待为等待 CPU 时间增量 ÷ 时间片数。缺少对应计数时显示“—”。PSI 是任务因等待 CPU 而受阻的时间占比。采集工具无法补出内核未提供的数据。</p></div></div><h4 class="subheading">每核 CPU 使用率</h4><div class="cores"><div v-for="(v,i) in metric.cpuPerCore" :key="i"><span>CPU {{metric.cpuCoreIDs?.[i]??i}}</span><el-progress :percentage="Number(v.toFixed(1))" :stroke-width="8"/></div></div></div>
<div class="data-card disk-section"><div class="disk-toolbar"><h4>磁盘 I/O 诊断</h4><el-select v-model="selectedDisk" filterable style="width:410px" aria-label="磁盘诊断设备"><el-option v-for="d in visibleDisks" :key="d.device" :value="d.device" :label="diskLabel(d)"/></el-select><el-checkbox v-model="showAllDisks">显示分区和光驱</el-checkbox></div><p v-if="currentDisk" class="topology">{{diskChain(currentDisk)}}{{currentDisk.mountpoints?.length?' → 挂载 '+currentDisk.mountpoints.join('、'):''}}</p><p class="note">整盘、分区和逻辑卷属于不同层级，同一笔 I/O 可能经过多层，指标不能跨层相加。优先选择可确认的根目录设备，否则选择整盘；以下四张图使用同一设备。旧版 exporter 未导出的映射关系显示为未提供。sr0 通常是光驱，默认折叠。</p><div class="charts"><MetricChart title="磁盘读写吞吐" :times="times" :series="io" unit="MiB/s" :gap-seconds="gap"/><MetricChart title="磁盘 IOPS" :times="times" :series="iops" unit="次/s" :gap-seconds="gap"/><MetricChart title="读写平均时延" :times="times" :series="latency" unit="ms" :gap-seconds="gap"/><MetricChart title="设备忙碌时间" :times="times" :series="diskBusy" unit="%" :max="100" :gap-seconds="gap"/></div><p class="note">读 / 写时延为采样区间耗时增量 ÷ 对应完成请求数，包含块层排队与处理时间；不是 P95/P99。没有完成请求时显示“—”，历史旧样本缺少新字段时留空。忙碌时间占比不等于设备性能上限。</p><el-table :data="visibleDisks" size="small" :row-class-name="diskRowClass"><el-table-column label="设备与用途" min-width="230"><template #default="{row}"><el-button text type="primary" @click="selectedDisk=row.device">{{diskName(row)}}</el-button><div class="note">{{diskKind(row)}} · {{row.mountpoints?.join('、')||'挂载关系未提供'}}</div></template></el-table-column><el-table-column label="上游设备" min-width="110"><template #default="{row}">{{row.backingDevices?.join('、')||row.parentDevice||'未提供'}}</template></el-table-column><el-table-column label="读时延" width="105"><template #default="{row}">{{ms(row.readAwaitMs)}}</template></el-table-column><el-table-column label="写时延" width="105"><template #default="{row}">{{ms(row.writeAwaitMs)}}</template></el-table-column><el-table-column label="综合时延" width="105"><template #default="{row}">{{row.readIOPS+row.writeIOPS?ms(row.awaitMs):'—'}}</template></el-table-column><el-table-column label="平均 I/O 队列" width="115"><template #default="{row}">{{row.averageQueue==null?'—':row.averageQueue.toFixed(2)}}</template></el-table-column><el-table-column label="在途 I/O" width="90"><template #default="{row}">{{row.inFlight??'—'}}</template></el-table-column><el-table-column label="忙碌时间" width="100"><template #default="{row}">{{row.utilization.toFixed(1)}}%</template></el-table-column></el-table></div>
<div class="data-card"><h4>磁盘容量与 inode</h4><el-table :data="metric.disks" size="small"><el-table-column prop="mountpoint" label="挂载点"/><el-table-column prop="device" label="设备"/><el-table-column label="总容量"><template #default="{row}">{{bytes(row.totalBytes)}}</template></el-table-column><el-table-column label="可用"><template #default="{row}">{{bytes(row.availableBytes)}}</template></el-table-column><el-table-column label="使用率" min-width="180"><template #default="{row}"><el-progress :percentage="Math.round(row.usedPercent)" :status="row.usedPercent>=90?'exception':undefined"/></template></el-table-column><el-table-column label="inode 使用"><template #default="{row}">{{row.inodes?row.inodeUsedPercent.toFixed(1)+'%':'未采集'}}</template></el-table-column></el-table></div>
<div class="data-card"><h4>网络详情</h4><el-table :data="metric.networks" size="small"><el-table-column prop="name" label="网卡"/><el-table-column label="累计入站"><template #default="{row}">{{bytes(row.receiveBytes)}}</template></el-table-column><el-table-column label="累计出站"><template #default="{row}">{{bytes(row.transmitBytes)}}</template></el-table-column><el-table-column prop="errors" label="累计错误"/><el-table-column prop="drops" label="累计丢包"/></el-table></div>
<el-alert v-for="w in metric.warnings" :key="w" :title="w" type="warning" :closable="false"/>
<p class="note">{{metric.os}} · {{metric.kernel}} · 运行 {{(metric.uptimeSeconds/86400).toFixed(1)}} 天。速率来自两次 HTTP 读取的计数差值，间隔约 {{metric.sampleSeconds?.toFixed(2)||'1'}} 秒；历史图表展示每 {{step}} 秒桶的最后样本，数据保留 48 小时，缺失区间留空。</p></template>
<el-empty v-else description="后台自动采集中，等待首个有效样本；采集失败时上方显示具体原因"/><el-dialog v-model="metricsDialog" title="node_exporter 指标地址" width="650px"><el-input v-model="metricsAddress" placeholder="http://服务器地址:9100/metrics"/><p class="note">留空使用主机地址的 9100 端口。由 dfops 后端通过 HTTP(S) 访问，无需 SSH 凭据。</p><template #footer><el-button @click="metricsDialog=false">取消</el-button><el-button type="primary" :loading="savingAddress" @click="saveAddress">保存并采集</el-button></template></el-dialog></div></template>
<style scoped>.host-monitor{display:flex;flex-direction:column;gap:16px;padding-bottom:20px}.heading,.actions,.collection,.collection>div{display:flex;align-items:center;gap:12px}.heading,.collection{justify-content:space-between}.heading h3{margin:5px 0}.heading small{font-weight:400;color:#7b8b9d;font-size:13px}.collection{padding:12px 16px;background:#fff;border:1px solid #e2e8f0;border-radius:7px;font-size:12px;color:#65758b}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.cards>div,.data-card{background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:18px}.cards span{color:#6e7e93;font-size:12px}.cards strong{display:block;font-size:28px;color:#243e60;margin-top:12px}.cards strong small{font-size:15px;margin-left:4px}.cards p{font-size:11px;color:#7b8b9d;margin:10px 0 0}.charts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.chart-wrap{position:relative;min-width:0}.chart-wrap>.el-select{position:absolute;width:110px;right:20px;top:42px;z-index:1}.data-card h4{margin:0 0 12px;font-size:13px}.note{font-size:12px;color:#7b8b9d;line-height:1.8}@media(max-width:1050px){.heading{align-items:flex-start;flex-direction:column}.cards{grid-template-columns:repeat(2,1fr)}.collection{flex-wrap:wrap}.charts{grid-template-columns:1fr}}.cpu-summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:18px;margin:18px 0;font-size:12px;color:#65758b}.cpu-summary strong{display:block;margin-top:10px;font-size:21px;color:#243e60}.cores{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:14px}.cores span{font-size:12px;color:#65758b}.subheading{margin-top:22px!important}.disk-toolbar{display:flex;align-items:center;gap:18px;flex-wrap:wrap}.disk-toolbar h4{margin:0}.topology{background:#f1f6fd;border-radius:5px;padding:12px;font-size:13px;color:#315a8d;overflow-wrap:anywhere;line-height:1.8}.capability{align-self:center;padding:20px}.disk-section :deep(.selected-device){--el-table-tr-bg-color:#edf5ff}.disk-section .el-button{padding:0}.cpu-summary+.note{margin-bottom:18px}@media(max-width:1050px){.cpu-summary{grid-template-columns:1fr 1fr}} .source-info{font-size:12px;color:#65758b;overflow-wrap:anywhere} </style>
